    def segments(size, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    row_segments = segments(h, separator_rows)
    col_segments = segments(w, separator_cols)

    counts = Counter(v for row in grid for v in row if v != separator)
    background = counts.most_common(1)[0][0]

    out = [[background for _ in col_segments] for _ in row_segments]
    for i, (r0, r1) in enumerate(row_segments):
