def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    def spans(n, cuts):
        out, start = [], 0
        for cut in cuts:
            if start < cut:
                out.append((start, cut))
            start = cut + 1
        if start < n:
            out.append((start, n))
        return out

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)

    source = None
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if any(grid[r][c] != background
                   for r in range(r0, r1) for c in range(c0, c1)):
                source = (r0, r1, c0, c1)
                break
        if source:
            break

    if source is None:
        return [row[:] for row in grid]

    r0, r1, c0, c1 = source
    tile = [row[c0:c1] for row in grid[r0:r1]]
    out = [row[:] for row in grid]

    for a, b in row_spans:
        for x, y in col_spans:
            for r in range(a, b):
                for c in range(x, y):
                    tr, tc = r - a, c - x
                    if tr < len(tile) and tc < len(tile[0]):
                        value = tile[tr][tc]
                        if value != background:
                            out[r][c] = value
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def edge_runs(side):
        if side in ("top", "bottom"):
            vals = grid[0 if side == "top" else h - 1]
        else:
            c = 0 if side == "left" else w - 1
            vals = [grid[r][c] for r in range(h)]

        runs = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            color = vals[i]
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            if j - i >= 2:
                runs.append((color, i, j - 1))
            i = j
        return runs

    candidates = []
    for side_a, side_b in (("top", "bottom"), ("left", "right")):
        for ca, a0, a1 in edge_runs(side_a):
            for cb, b0, b1 in edge_runs(side_b):
                if ca == cb:
                    la, lb = a1 - a0 + 1, b1 - b0 + 1
                    candidates.append((min(la, lb), -abs(la - lb),
                                       side_a, side_b, ca, a0, a1, b0, b1))

    if not candidates:
        return [row[:] for row in grid]

    _, _, side_a, side_b, border, a0, a1, b0, b1 = max(candidates)
    out = [row[:] for row in grid]

    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != border]
    if not markers:
        return out
    marker_color = Counter(grid[r][c] for r, c in markers).most_common(1)[0][0]

    def edge_coord(side):
        return {"top": 0, "bottom": h - 1, "left": 0, "right": w - 1}[side]

    def side_bounds(side):
        return (a0, a1) if side == side_a else (b0, b1)

    def paint_actual(r, c, side, color):
        if side == "top":
            for rr in range(1, r):
                out[rr][c] = color
        elif side == "bottom":
            for rr in range(r + 1, h - 1):
                out[rr][c] = color
        elif side == "left":
            for cc in range(1, c):
                out[r][cc] = color
        else:
            for cc in range(c + 1, w - 1):
                out[r][cc] = color

    for r, c in markers:
        t = c if side_a in ("top", "bottom") else r
        in_a = a0 <= t <= a1
        in_b = b0 <= t <= b1

        if in_a and not in_b:
            chosen, paired = side_a, side_b
        elif in_b and not in_a:
            chosen, paired = side_b, side_a
        elif in_a and in_b:
            da = abs((r if side_a in ("top", "bottom") else c) -
                     edge_coord(side_a))
            db = abs((r if side_b in ("top", "bottom") else c) -
                     edge_coord(side_b))
            chosen, paired = (side_a, side_b) if da <= db else (side_b, side_a)
        else:
            da = min(abs(t - a0), abs(t - a1))
            db = min(abs(t - b0), abs(t - b1))
            chosen, paired = (side_a, side_b) if da <= db else (side_b, side_a)

        paint_actual(r, c, chosen, marker_color)

        lo, hi = side_bounds(chosen)
        other_lo, other_hi = side_bounds(paired)
        mapped = other_lo + (t - lo)
        if not (other_lo <= mapped <= other_hi):
            continue

        if side_a in ("top", "bottom"):
            for rr in range(h):
                if grid[rr][mapped] != border:
                    out[rr][mapped] = marker_color
        else:
            for cc in range(w):
                if grid[mapped][cc] != border:
                    out[mapped][cc] = marker_color

    for r, c in markers:
        out[r][c] = 4
    return out

