    return out

def transform(grid):
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    out = [[background for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != background:
                out[r + 1][c] = grid[r][c]
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Each function identifies a family of parallel stripes.
    orientations = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: c - r,
        lambda r, c: c + r,
    ]

    candidates = []
    for orient in orientations:
        groups = {}
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    q = orient(r, c)
                    groups.setdefault(q, set()).add(v)

        # A stripe must contain only one non-background color.
        if not groups or any(len(vals) != 1 for vals in groups.values()):
            continue
        known = {q: next(iter(vals)) for q, vals in groups.items()}

        for period in range(1, max(h, w) + 1):
            residues = {}
            valid = True
            for q, color in known.items():
                k = q % period
                if k in residues and residues[k] != color:
                    valid = False
                    break
                residues[k] = color
            if valid:
                strength = sum(len(vals) ** 2 for vals in groups.values())
                candidates.append((period, -len(residues), -strength,
                                   orient, residues))
                break

    if not candidates:
        return [row[:] for row in grid]

    _, _, _, orient, residues = min(candidates, key=lambda x: x[:3])
    period = min(x[0] for x in candidates
                 if x[3] is orient and x[4] == residues)

    # Fill any unobserved motif positions from the nearest observed position.
    motif = []
    for k in range(period):
        if k in residues:
            motif.append(residues[k])
        else:
            nearest = min(residues, key=lambda j: min((k - j) % period,
                                                       (j - k) % period))
            motif.append(residues[nearest])

    return [[motif[orient(r, c) % period] for c in range(w)]
            for r in range(h)]

