    left_w = sep
    right_w = w - sep - 1
    n = min(left_w, right_w)
    return [
        [2 if grid[r][c] != 0 and grid[r][sep + 1 + c] != 0 else 0
         for c in range(n)]
        for r in range(h)
    ]

def transform(grid):
